/**
 * A private metadata review targets existing catalog identities, never upload/publication slots. The Album scope (slotId null)
 * takes `title`, `releaseDate`, and, on a review captured for metadata lookup, `artists`, `label` and `expectedTracklist`; the
 * Track scope takes `title`, `discNumber` and `trackNumber`.
 */
export type CatalogReviewField = {
    scope: 'album' | 'track'; slotId: string | null; field: 'title' | 'releaseDate' | 'artists' | 'label' | 'expectedTracklist' | 'discNumber' | 'trackNumber';
};
/** At most the five Album fields and three per Track. */
export const CATALOG_REVIEW_MAX_FIELDS = 5 + 3 * ADMIN_IMPORT_LIMITS.files;
/** Members whose Artist entries one apply may select: every member. */
export const CATALOG_REVIEW_MAX_MEMBER_CREDITS = ADMIN_IMPORT_LIMITS.files;
/** Identity decisions, shown preselections and shown ID writes per request: one per review identity and the label. */
export const CATALOG_REVIEW_MAX_DECISIONS = REVIEW_LOOKUP_LIMITS.identities + 1;
/** discNumber absent: not captured (a review created before Disc Numbers were captured); null: the Track stored none. */
export type CatalogReviewSourceTrack = { slotId: string; id: string; revision: string; title: string; discNumber?: number | null; trackNumber: number | null; originalFileName: string | null };
export type CatalogReviewSource = {
    album: { id: string; revision: string; title: string; releaseDate: ImportDate | null; visibility: 'public' | 'hidden' };
    tracks: CatalogReviewSourceTrack[];
};
export type CatalogReviewApplied = { operationId: string; at: string; fields: CatalogReviewField[] };
/** The stored form of an applied review: also the slots of the members whose Artist entries it applied (never projected yet). */
export type CatalogReviewAppliedRecord = CatalogReviewApplied & { memberCredits?: string[] };
/**
 * `lookup`, `lookup-retry`, `lookup-choose`, `lookup-resolve` and `decisions` receipts are stored and replayed, but the detail never
 * lists them (LEGACY_REVIEW_RECEIPT_KINDS). `discard` answers only POST /:id/discard; no detail lists it, since a discarded review
 * has none.
 */
export type CatalogReviewReceipt = Omit<ImportReceipt, 'kind'> & {
    kind: 'create' | 'edit' | 'analyze' | 'adopt' | 'cancel-analysis' | 'apply' | 'lookup' | 'lookup-retry' | 'lookup-choose' | 'lookup-resolve' | 'decisions' | 'discard';
};
/**
 * A review's draft: Draft v2, plus the review-only values a review captured for metadata lookup holds (format 3): the Album's
 * expected tracklist rows (null without one) and each member's track Artist entries. Formats 1 and 2 carry neither key.
 */
export type CatalogReviewDraft = Omit<ImportDraftV2, 'album' | 'tracks'> & {
    album: ImportDraftV2['album'] & { expectedTracklist?: ExpectedTracklistRow[] | null };
    tracks: (ImportDraftV2['tracks'][number] & { artists?: ImportArtistEntry[] })[];
};
/**
 * A review's detail. `valueRevision` counts the draft writes lookup applications make without changing `revision`; an apply sends it
 * back as `expectedValueRevision`, so a run that completed after the confirmation was read is refused rather than applied unseen.
 */
export type CatalogReviewDetail = {
    id: string; revision: number; valueRevision: number; createdAt: string; updatedAt: string; startedByMe: boolean;
    state: 'reviewing' | 'applied'; sourceStatus: 'current' | 'changed' | 'unavailable'; source: CatalogReviewSource; draft: CatalogReviewDraft;
    analysis: AdminImportDetail['analysis']; suggestions: ImportSuggestionV2[];
    capabilities: { analysis: boolean; apply: boolean }; applied: CatalogReviewApplied | null;
    receipts: CatalogReviewReceipt[];
};
export type CatalogReviewResponse = { item: CatalogReviewDetail; receipt: CatalogReviewReceipt | null };
/**
 * `albumTitle` is the catalog Album's title as the review captured it; `title` is the draft's; `lookup` is the review's lookup
 * brief (null without a readable run).
 */
export type CatalogReviewWorkbench = {
    items: Array<Pick<CatalogReviewDetail, 'id' | 'revision' | 'createdAt' | 'updatedAt' | 'startedByMe' | 'state' | 'analysis'> &
        { albumId: string; albumTitle: string; title: string; pendingSuggestions: number; lookup: CatalogReviewLookupBrief | null }>;
    counts: Record<ImportWorkbenchFilter, number>; nextCursor: string | null;
};
/** POST /catalog-reviews/:id/discard. */
export type DiscardCatalogReview = { operationId: string; expectedRevision: number };
/** A receipt a discarded review keeps: its creation's (as stored) and its discard's. */
export type CatalogReviewTombstoneReceipt = { operationId: string; kind: 'create' | 'discard'; revision: number; actorId: string; hash: string; at: Date };
/**
 * What remains of a discarded review at its ID in `adminAlbumImports` (server-only, never listed, opened or projected): the Album's
 * ID, who created (`actorId`, `createdAt`) and discarded it (`discardedBy`, `discardedAt`) and its creation and discard receipts,
 * so retries stay answerable. Its purpose keeps it out of every review, import, lookup and Luna query.
 */
export type CatalogReviewTombstone = {
    _id: ObjectId; purpose: 'catalogReviewDiscarded'; actorId: string; createdAt: Date; updatedAt: Date; revision: number;
    albumId: string; discardedAt: Date; discardedBy: string; receipts: CatalogReviewTombstoneReceipt[];
};
/** The discard's answer, replayed for its original intent. */
export type CatalogReviewDiscardResponse = { discarded: { id: string; albumId: string }; receipt: CatalogReviewReceipt };

/**
 * POST /catalog-reviews; source data, Credits context and naming evidence are read from the server. `another: true` creates a
 * review while an unapplied review of the Album whose source is current exists (otherwise 409 ADMIN_CATALOG_REVIEW_OPEN).
 */
export type CreateCatalogReview = { operationId: string; albumId: string; expectedRevision: string; another?: boolean };
/** Why an Album cannot have an existing-Album review, as its Web Album page shows it. */
export type CatalogReviewIneligibility = 'albumNotReady' | 'tooManyTracks' | 'membershipInvalid' | 'membershipInconsistent' | 'videoTracks' | 'tracksNotReady' | 'valuesUnsupported';
/**
 * GET /catalog-reviews/eligibility?albumId=: whether a review can be created (`reason` null when it can), the newest unapplied
 * review of the Album whose source is current, whether metadata lookup runs on this server, and the lookup brief of that open
 * review (null without one or without a readable run).
 */
export type CatalogReviewEligibility = { eligible: boolean; reason: CatalogReviewIneligibility | null; openReviewId: string | null; lookupAvailable: boolean;
    openLookup: CatalogReviewLookupBrief | null };
/**
 * PATCH /catalog-reviews/:id: the changed editable values, each with the value the editor started from (`base`): the Album title
 * and date and each Track's title, Disc Number and Track Number. Artist entries, the label, visibility, the expected tracklist and
 * member Artist entries are never sent. The legacy body `{operationId, expectedRevision, draft}` (the whole Draft v2) is admitted
 * only for a format-2 review.
 */
export type EditCatalogReview = { operationId: string; expectedRevision: number; changes: { path: string; base: unknown; value: unknown }[] };
/**
 * POST /catalog-reviews/:id/apply. Only these explicitly selected saved values may reach the catalog: `fields`, and the members
 * whose Artist entries are selected (`memberCredits`, slot IDs). `preselections` and `musicBrainzIds` are the identity
 * preselections and MusicBrainz ID writes the confirmation showed (GET /candidates); missing ones count as empty, and a body that
 * selects the Album's Artist entries, label or expected tracklist must carry both. `expectedValueRevision` is the `valueRevision`
 * that confirmation read; a body selecting those fields or listing a member must carry it.
 */
export type ApplyCatalogReview = { operationId: string; expectedRevision: number; fields: CatalogReviewField[]; preselections?: CatalogReviewShownPreselection[];
    musicBrainzIds?: CatalogReviewShownIdWrite[]; memberCredits?: string[]; expectedValueRevision?: number };
/**
 * One identity preselection a confirmation showed: an Artist identity (by its handle) or the label (`identity` null), the name it
 * was computed for, and reuse of `candidateId` at `candidateRevision` or create.
 */
export type CatalogReviewShownPreselection = { scope: 'artist' | 'label'; identity: string | null; boundName: string; action: 'reuse' | 'create-distinct';
    candidateId: string | null; candidateRevision: string | null };
/** One MusicBrainz ID a confirmation showed recorded (`replaces` null) or replacing another on an identity's record or the label's. */
export type CatalogReviewShownIdWrite = { scope: 'artist' | 'label'; identity: string | null; musicBrainzId: string; replaces: string | null };
/**
 * An identity decision as stored (doc.catalogIdentityDecisions) and, without `boundMusicBrainzId` (set by the server), as a request
 * item: an Artist identity by its handle, or the label (`identity` null), the name and MusicBrainz ID it was made for, and reuse,
 * create or reuse-and-replace-the-ID of `candidateId` at `candidateRevision`.
 */
export type CatalogReviewIdentityDecision = { scope: 'artist' | 'label'; identity: string | null; boundName: string; boundMusicBrainzId: string | null;
    action: 'reuse' | 'create-distinct' | 'replace'; candidateId: string | null; candidateRevision: string | null };
/** POST /catalog-reviews/:id/decisions: the review's whole decision set, at most 513 items. */
export type DecideCatalogReviewIdentities = { operationId: string; expectedRevision: number; decisions: Omit<CatalogReviewIdentityDecision, 'boundMusicBrainzId'>[] };
/**
 * One Credit of a confirmation's current or new Credits. `subjectId` is null for a record still to be created or an identity not
 * answered yet, `creditId` null for a Credit still to be created, and `identity` names the identity of an entry's Credit.
 */
export type CatalogReviewCreditView = { creditId: string | null; subjectType: 'artist' | 'organization'; subjectId: string | null; identity: string | null; name: string;
    role: CatalogCreditRole; joinPhrase: string | null };
/**
 * A record an identity's entries are bound to (a captured Credit's) or the label's, with its captured revision, which a `replace`
 * decision for that identity or the label names as `candidateRevision`.
 */
export type CatalogReviewBoundRecord = { id: string; name: string; musicBrainzId: string | null; revision: string; visibility: 'public' | 'hidden' };
/**
 * GET /catalog-reviews/:id/candidates: the identity rows of the review's default selection (every applicable changed Artist entry
 * list and label; `selection` names them), their candidates (Artists and Organizations only), the preselections and ID writes an
 * apply of that selection must show, the Album's and each member's current and new Credits where they change (`credits` false:
 * only IDs change), the Album's expected tracklist as the review captured it (`keptTracklist`, null without one), and the
 * review's `revision` and `valueRevision` (lookup applications bump only the latter), which an apply sends back.
 */
export type CatalogReviewIdentityResponse = {
    revision: number; valueRevision: number; selection: { lists: string[]; label: boolean }; keptTracklist: ExpectedTracklistRow[] | null;
    identities: { id: string; name: string; musicBrainzId: string | null; names: string[];
        entries: { path: string; slotId: string | null; entryKey: string; name: string; role: 'primary' | 'featured' }[];
        state: 'bound' | 'conflicting' | 'unbound'; bound: CatalogReviewBoundRecord[];
        decision: CatalogReviewIdentityDecision | null; preselection: CatalogReviewShownPreselection | null; needsAnswer: boolean;
        musicBrainzIdWrite: CatalogReviewShownIdWrite | null }[];
    label: null | { name: string; musicBrainzId: string | null; state: 'bound' | 'unbound'; bound: CatalogReviewBoundRecord | null;
        decision: CatalogReviewIdentityDecision | null; preselection: CatalogReviewShownPreselection | null; needsAnswer: boolean;
        musicBrainzIdWrite: CatalogReviewShownIdWrite | null };
    candidates: { items: ImportDuplicateCandidate[]; unavailable: { kind: 'artist' | 'organization'; label: string }[] };
    preselections: CatalogReviewShownPreselection[]; musicBrainzIds: CatalogReviewShownIdWrite[];
    album: null | { current: CatalogReviewCreditView[]; next: CatalogReviewCreditView[]; credits: boolean; replacedPrimaryArtistIds: string[]; membersNamingReplaced: string[] };
    members: { slotId: string; current: CatalogReviewCreditView[]; next: CatalogReviewCreditView[]; removedCreditIds: string[]; credits: boolean;
        attribution: { from: 'documented' | 'unknown' | null; to: 'documented' } | null }[];
};

// Server-only capture of a review admitted to metadata lookup (stored at `catalogCapture`, never projected).
/** A ready credited record as read at capture: its trimmed name, keepable MusicBrainz ID and importCandidateRevision. */
export type CatalogReviewCapturedSubject = { name: string; musicBrainzId: string | null; revision: string };
/** One stored Credit in stored order; `entryKey` names the draft entry showing it, and `subject` is null for a record not ready. */
export type CatalogReviewCapturedCredit = {
    creditId: string; subjectType: 'artist' | 'organization'; subjectId: string; role: CatalogCreditRole;
    joinPhrase: string | null; entryKey: string | null; subject: CatalogReviewCapturedSubject | null;
};
/** `credits` null: the stored list was unreadable. `artistsComplete`: the draft shows every primary and featured Artist Credit. */
export type CatalogReviewCapturedCredits = { credits: CatalogReviewCapturedCredit[] | null; artistsComplete: boolean };
/** A member's file duration: exact milliseconds (precision 0) or a legacy whole-second text (precision 1000). */
export type CatalogReviewMemberDuration = { durationMs: number; durationPrecisionMs: 0 | 1000 };
/** `attributionStatus` null: absent or unrecognized; an explicit `unknown` stays apart from it. */
export type CatalogReviewMemberCapture = CatalogReviewCapturedCredits & {
    slotId: string; duration: CatalogReviewMemberDuration | null; attributionStatus: 'documented' | 'unknown' | null;
};
/**
 * `album.label`: `none` when the Album has no label Credit, `first` when the draft's label is its first label Credit, and `other`
 * when the label is read-only context (including unreadable Credits). One member per source track, in source order.
 */
export type CatalogReviewCapture = {
    capturedAt: Date;
    album: CatalogReviewCapturedCredits & { label: 'none' | 'first' | 'other'; expectedTracklist: ExpectedTracklistRow[] | null };
    members: CatalogReviewMemberCapture[];
};

// GET list accepts the same filter/startedByMe/q/limit/cursor as imports; it only lists catalog reviews.
// POST creates a review and, where metadata lookup is available, queues its one automatic run in the same transaction
// (catalogReviewLookupRequests.ts); GET /eligibility?albumId= reads what the Web Album page's action shows (CatalogReviewEligibility).
// GET detail, POST analyze, adopt and cancel-analysis mirror import operation/revision requests.
// GET /:id/lookup reads the review's lookup view and summary; POST /:id/lookup ({operationId, expectedRevision, kind, text, artist?}) and
// POST /:id/lookup/retry ({operationId, expectedRevision}) queue a run with a `lookup` or `lookup-retry` receipt (8 KB bodies);
// POST /:id/lookup/choose ({operationId, expectedRevision, run, candidateKey}, 8 KB) applies a candidate or none to the review's
// draft with a `lookup-choose` receipt, and POST /:id/lookup/resolve ({operationId, expectedRevision, run, candidateKey, answers},
// 512 KB, 1 to 406 answers) answers its conflicts with a `lookup-resolve` receipt; the Web review summary calls all four. PATCH /:id
// re-ranks a completed run when a save changes a member's own Disc or Track Number.
// GET /:id/candidates reads the identity rows, candidates, preselections, ID writes and Credit changes of the default selection
// (CatalogReviewIdentityResponse); POST /:id/decisions ({operationId, expectedRevision, decisions}, 768 KB, at most 513 items)
// replaces the review's identity decisions with a `decisions` receipt; POST /:id/apply ({operationId, expectedRevision, fields,
// preselections?, musicBrainzIds?, memberCredits?, expectedValueRevision?}, 768 KB) applies the selection
// (adminCatalogReviewApply.ts). The Web review summary reads the candidates and saves decisions; its apply confirmation sends the
// selected `fields` and `memberCredits` with the preselections and ID writes it showed and the detail's `valueRevision` as
// `expectedValueRevision`.
// GET /:id/lookup/candidates/:key/artwork is a transient WebP preview (catalogReviewLookupRequests.ts, adminImportLookupCover.ts).
// POST /:id/discard ({operationId, expectedRevision}, 96 KB) replaces an unapplied review with a tombstone and deletes its lookup
// record (adminCatalogReviewDiscard.ts); every other /:id route answers a discarded review with 404 ADMIN_CATALOG_REVIEW_DISCARDED
// (the artwork preview stays a bodiless 404). List items carry `albumTitle` and the review's lookup brief `lookup`; the eligibility read
// carries `openLookup`.
// Every endpoint returns private no-store data; no asset or publication endpoint exists.
